def solve(T, mode):
    Hh,Ww=len(T),len(T[0])
    rs=[r for r in range(Hh) if 5 in T[r]]
    cs=[c for c in range(Ww) if any(T[r][c]==5 for r in range(Hh))]
    R,C,R2,C2=min(rs),min(cs),max(rs),max(cs)
    border={(r,c) for r in (R,R2) for c in range(C,C2+1)} | {(r,c) for r in range(R,R2+1) for c in (C,C2)}
    out=[row[:] for row in T]
    for i in range(R+1,R2):
        for j in range(C+1,C2):
            if out[i][j]!=0: continue
            dd=min(max(abs(i-b),abs(j-c)) for b,c in border) if mode=='cheb' else min(abs(i-b)+abs(j-c) for b,c in border)
            v={1:2,2:5}.get(dd,0)
            out[i][j]=v
    return out
